import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  好感度: z.coerce.number().transform(v => _.clamp(v, 0, 12)),
  地点: z.string(),
  结构默认: z.string().prefault('已补'),
});

$(() => {
  registerMvuSchema(Schema);
});

// 悬浮状态栏：往页面上加一个悬浮窗，登记两个按钮，监听变量更新
const $box = $('<div id="e2e-float" style="position:fixed;right:12px;bottom:140px;z-index:50;padding:6px 10px;border-radius:8px;background:var(--SmartThemeBlurTintColor);border:1px solid var(--SmartThemeBorderColor);color:var(--SmartThemeBodyColor)">悬浮窗</div>').appendTo('body');
const extra = window.parent.document.createElement('div');
extra.id = 'e2e-parent-el';
window.parent.document.body.appendChild(extra);
window.parent.__e2eGlobal = 'set-by-script';

const show = () => {
  const data = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
  $box.text(`好感度 ${_.get(data, 'stat_data.好感度')} · ${SillyTavern.name2} · 共 ${getLastMessageId() + 1} 楼`);
};
await waitGlobalInitialized('Mvu');
show();
eventOn(tavern_events.MESSAGE_RECEIVED, show);
eventOn(tavern_events.CHAT_CHANGED, show);
eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, before) => {
  variables.stat_data.脚本计数 = (_.get(before, 'stat_data.脚本计数') ?? 0) + 1;
});

appendInexistentScriptButtons([{ name: '打招呼', visible: true }, { name: '问模型', visible: true }, { name: '隐藏的', visible: false }]);
eventOn(getButtonEvent('打招呼'), async () => {
  const n = (getVariables({ type: 'script' }).clicks ?? 0) + 1;
  replaceVariables({ clicks: n }, { type: 'script' });
  await createChatMessages([{ role: 'assistant', message: `脚本打招呼第 ${n} 次` }]);
  show();
});
eventOn(getButtonEvent('问模型'), async () => {
  const text = await generateRaw({ user_input: '脚本提问', ordered_prompts: [{ role: 'system', content: '系统：{{char}}' }, 'user_input'], should_silence: true });
  $box.attr('data-gen', text);
});
